INSERT INTO trechos (id, texto, publico, macronarrativa, pauta, tipo, forca, link, pagina) VALUES ('D01-TR-054-60', 'Cuidar é proteger a vida concreta, mas também devolver às mulheres o direito de fazer planos.', '60+', 'família e cuidado', 'segurança pública', 'funciona', NULL, NULL, '23'), ('D01-TR-060-60', 'Não é sobre anunciar mais uma lei, é sobre provar que alguma coisa mudou.', '60+', 'família e cuidado', 'segurança pública', 'funciona', NULL, NULL, '25'), ('D01-TR-065-60', 'O cuidado não pode depender só da força individual da mãe: a rede de assistência deve cuidar de quem cuida, e a imagem da "mãe heroica que dá conta de tudo sozinha" precisa ser quebrada.', '60+', 'família e cuidado', 'rede de apoio', 'funciona', NULL, NULL, '26'), ('D01-TR-066-60', 'Responder à violência com caminho prático, não com campanha genérica; a proteção digital dos filhos é a porta de entrada mais aberta desse território, e feminicídio é lugar delicado de diálogo, pois não há sensação de segurança com as soluções disponíveis.', '60+', 'família e cuidado', 'proteção da infância', 'funciona', NULL, NULL, '26'), ('D01-TR-067-60', 'Ancorar o sonho na segurança: quando o cuidado funciona, sobra espaço para estudar, descansar e sonhar, o direito de sonhar além da sobrevivência.', '60+', 'família e cuidado', 'rede de apoio', 'funciona', NULL, NULL, '26'), ('D09-TR-028', '"E a minha vida, graças a Deus, com saúde a gente acha que está boa. A saúde da gente é tudo."', '60+', 'família e cuidado', 'saúde e sus', 'verbatim', NULL, NULL, '7'), ('D09-TR-032', '"Aparecem as doenças, a depressão que está ganhando o mundo inteiro. A saúde está muito ruim para nós. Péssima."', '60+', 'família e cuidado', 'saúde e sus', 'verbatim', NULL, NULL, '8'), ('D09-TR-033', '"Se um de nós aqui a mais de 70 anos for mexer com moleque de 16 anos, eles vão bater em nós porque nós não temos mais defesa nenhuma no nosso corpo. Nós já somos lento, de natureza, pela idade."', '60+', 'família e cuidado', 'segurança pública', 'verbatim', NULL, NULL, '8'), ('D09-TR-050', '"Tem coisas que eles não deixam eu sair sozinha. Não é que eles não deixem, eles têm muito cuidado comigo. Vou na padaria, falam: ''Mãe, cuidado para atravessar a rua''."', '60+', 'família e cuidado', 'rede de apoio', 'verbatim', NULL, NULL, '10'), ('D09-TR-051', '"Mas agora eu sou viúva. Então meus filhos, meus netos, cada um tem a sua vida e eu moro sozinha. Então eu gosto da minha companhia."', '60+', 'família e cuidado', 'moradia e cidade', 'verbatim', NULL, NULL, '10'), ('D09-TR-052', '"Nesses dois últimos anos que eu estou fora do trabalho, eu me sinto assim um pouco reclusa nesta situação. A gente já não se fala tanto. Até porque eu acabei ficando sozinha em casa, porque os filhos todos saíram."', '60+', 'família e cuidado', 'saúde mental', 'verbatim', NULL, NULL, '10'), ('D09-TR-054', '"Mais respeito para com o idoso é que precisava, começar da família dentro de casa. Muitas vezes nós somos desrespeitados não só na sociedade, mas também dentro de casa. Ter uma lei a nosso favor, porque se um filho maltrata a gente, a gente ter onde contar com uma ajuda do governo."', '60+', 'família e cuidado', 'envelhecimento e autonomia', 'verbatim', NULL, NULL, '10'), ('D09-TR-055', '"Ter um espaço onde eles pudessem morar e se divertirem. Ter uma academia, quem gosta de dançar, dançar. Ter um lugar onde eles têm os jogos para fazer dama, dominó, essas coisas que preencham a cabeça deles já que os filhos não ligam."', '60+', 'família e cuidado', 'cultura e lazer', 'verbatim', NULL, NULL, '10'), ('D09-TR-057', '"Muitos filhos fazem isso, descartam, não querem mais saber da gente, não querem cuidar."', '60+', 'família e cuidado', 'envelhecimento e autonomia', 'verbatim', NULL, NULL, '10'), ('D09-TR-068', '"O SUS para mim está muito devagar. Eu estou com uma ruma de exame aqui, eu não consigo marcar e nem fazer. Aí eu tenho que pagar."', '60+', 'família e cuidado', 'saúde e sus', 'verbatim', NULL, NULL, '12'), ('D01-TR-084-60', 'O vínculo mais seguro com o país nasce do cotidiano: família, comida, humor, cuidado, território, com o orgulho regional (nordestino/baiano) como camada extra de identidade.', '60+', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '31'), ('D03-TR-070-60', 'A defesa do Brasil no exterior recebe 24,8% de avaliação ótima ou boa e 34,5% ruim ou péssima, com 15,2% sem saber avaliar, a maior taxa de não avaliação entre as áreas.', '60+', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '73'), ('D03-TR-071-60', 'A proteção ao meio ambiente na gestão federal recebe 23,2% de avaliação ótima ou boa e 37,8% ruim ou péssima.', '60+', 'brasil e pertencimento', 'clima', 'achado', 'indício', NULL, '73'), ('D03-TR-087-60', 'O Programa Brasil Soberano é o menos conhecido da lista (15,9%); a avaliação registrada é 35,5% ótima ou boa, 14,8% ruim ou péssima e 22,2% não sabem avaliar.', '60+', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '76'), ('D07-TR-002-60', 'A defesa do país no exterior aparece entre as três áreas de maior peso na avaliação pública de desempenho governamental, acima de áreas de serviço de uso direto.', '60+', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '3'), ('D07-TR-005-60', 'Proteção ao meio ambiente tem peso muito baixo na formação da avaliação pública de desempenho governamental.', '60+', 'brasil e pertencimento', 'clima', 'achado', 'indício', NULL, '3'), ('D07-TR-024-60', 'Defesa do Brasil no exterior consta na lista de temas cuja menção deve ser evitada no momento.', '60+', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '5'), ('D07-TR-032-60', 'Na Região Sudeste, a defesa do país no exterior é a área de maior peso na avaliação de desempenho governamental, à frente de custo de vida.', '60+', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '7'), ('D07-TR-034-60', 'Na Região Sudeste, proteção ao meio ambiente tem peso na avaliação cerca do dobro do observado no conjunto do país, ainda que em patamar baixo.', '60+', 'brasil e pertencimento', 'clima', 'achado', 'indício', NULL, '7'), ('D07-TR-037-60', 'Na Região Centro-Oeste, proteção ao meio ambiente ocupa a quarta posição em peso na avaliação, contraste marcado com a última posição no conjunto do país.', '60+', 'brasil e pertencimento', 'clima', 'achado', 'indício', NULL, '8'), ('D07-TR-038-60', 'Na Região Centro-Oeste, a defesa do país no exterior ocupa posição de peso mais baixa na avaliação do que no conjunto do país.', '60+', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '8'), ('D07-TR-042-60', 'Na Região Nordeste, a defesa do país no exterior ocupa posição de peso muito mais baixa na avaliação do que no conjunto do país.', '60+', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '9'), ('D09-TR-201', 'Imagens de crianças e jovens estudando e caminhando livremente evocam de imediato o desejo de deixar um país próspero e seguro; o idoso aceita dor e cansaço do deslocamento para não deixar "uma porcaria de país".', '60+', 'brasil e pertencimento', 'futuro possível', 'achado', 'forte', NULL, '39'), ('D01-TR-086-60', 'A associação do brasileiro a "preguiçoso" é rejeitada com força.', '60+', 'brasil e pertencimento', 'orgulho e identidade nacional', 'afasta', NULL, NULL, '32'), ('D09-TR-148-bra', 'Falar dos 70+ como um bloco único afasta: há idosos ativos e passivos, e a heterogeneidade é a regra.', '60+', 'brasil e pertencimento', 'envelhecimento e autonomia', 'afasta', NULL, NULL, '4'), ('D09-TR-149-bra', 'Associar velhice a passividade, ao idoso "trancado em uma sala na frente de uma televisão", afasta: para muitos, a mobilização física e social é resistência ao papel de descarte.', '60+', 'brasil e pertencimento', 'respeito ao idoso', 'afasta', NULL, NULL, '6'), ('D09-TR-161', 'Para este público, o futuro que importa é o dos descendentes: já viveram a maior parte da vida e canalizam expectativas para filhos, netos e bisnetos.', '60+', 'brasil e pertencimento', 'futuro possível', 'contexto', NULL, NULL, '23'), ('D09-TR-202', 'Mostrar crianças e jovens estudando e circulando em segurança aproxima: ativa o desejo de herdar um país viável para filhos, netos e bisnetos.', '60+', 'brasil e pertencimento', 'futuro possível', 'funciona', NULL, NULL, '39'), ('D01-TR-081-60', '"O Pix é nosso, o SUS pode ser melhor, e o Brasil presta"', '60+', 'brasil e pertencimento', 'orgulho e identidade nacional', 'verbatim', NULL, NULL, '30'), ('D01-TR-002-60', 'A decisão de voto do público indeciso ancora-se na percepção concreta da própria vida, não na identidade política.', '60+', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '6'), ('D01-TR-027-60', 'Há competência real de gestão cotidiana (casa, filhos, negócio e dinheiro), a mesma usada para avaliar quem cumpriu e quem só prometeu; não é preciso ensinar este público a pensar politicamente.', '60+', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '17'), ('D01-TR-143-60', 'O Legislativo é pouco compreendido, um grande ponto cego: perguntadas sobre o papel do Senado, as respostas variam entre acerto parcial, confusão com outros cargos e desconhecimento assumido sem constrangimento.', '60+', 'participação e voz', 'funcionamento do legislativo', 'achado', 'indício', NULL, '55'), ('D03-TR-013-60', 'O WhatsApp é a rede de uso mais universal: 87,3% da população utiliza todos os dias e apenas 7,2% nunca ou quase nunca utiliza.', '60+', 'participação e voz', 'informação e desinformação', 'achado', 'indício', NULL, '20'), ('D03-TR-059', 'Em 2025, entre pessoas com 70 anos ou mais, para quem o voto é facultativo, 74,4% pretendiam votar nas eleições de 2026. A intenção de participação é maior no Norte (80,9%) e no Nordeste (78,6%) e menor no Sul (66,6%).', '60+', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '53'), ('D03-TR-104-60', 'Família e fé são apontados como os valores que mais mobilizam o voto.', '60+', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '97'), ('D07-TR-020-60', 'Os temas de maior impacto são identificados como os preditores do voto, positivos para a situação e negativos para a oposição.', '60+', 'participação e voz', 'comunicação e linguagem', 'achado', 'indício', NULL, '1'), ('D09-TR-008', 'Entre os participantes deste estudo, a tendência majoritária é estar de bem com a vida, encontrando razões para continuar lutando apesar de queixas numerosas.', '60+', 'participação e voz', 'envelhecimento e autonomia', 'achado', 'forte', NULL, '5'), ('D09-TR-009', 'O estado geral da saúde e a autoimagem física são os pilares sobre os quais se estruturam a autonomia, a socialização e o exercício da cidadania.', '60+', 'participação e voz', 'saúde e sus', 'achado', 'indício', NULL, '5'), ('D09-TR-010', 'Há correlação direta entre bem-estar físico e sentimento de utilidade e participação social.', '60+', 'participação e voz', 'saúde e sus', 'achado', 'indício', NULL, '5'), ('D09-TR-059', 'Entre os participantes deste estudo, há convergência quanto à percepção de que os idosos merecem ser mais bem tratados e respeitados pela sociedade e pela política em geral.', '60+', 'participação e voz', 'respeito ao idoso', 'achado', 'forte', NULL, '11'), ('D09-TR-074', 'Falar em política no contexto do processo eleitoral que se aproxima traz à tona um espectro emocional dominado por desânimo, fadiga e desconfiança.', '60+', 'participação e voz', 'cansaço cívico', 'achado', 'indício', NULL, '13'), ('D09-TR-075', 'Parte expressiva dos entrevistados relata apatia e perda de entusiasmo cívico, admitindo que o processo eleitoral se tornou cansativo e repetitivo.', '60+', 'participação e voz', 'cansaço cívico', 'achado', 'indício', NULL, '13'), ('D09-TR-076', 'A expressão desiludido com os políticos surge como padrão verbal recorrente.', '60+', 'participação e voz', 'cansaço cívico', 'achado', 'forte', NULL, '13'), ('D09-TR-078', 'O sentimento de fadiga está associado à percepção de que nada muda apesar de anos sucessivos de promessas.', '60+', 'participação e voz', 'promessa e entrega', 'achado', 'indício', NULL, '13'), ('D09-TR-079', 'Há reconhecimento de que algumas coisas melhoraram em gestões anteriores, mas o descumprimento de promessas segue sendo a marca atribuída aos políticos brasileiros, o que alimenta a pergunta sobre por que continuar votando.', '60+', 'participação e voz', 'promessa e entrega', 'achado', 'indício', NULL, '13'), ('D09-TR-083', 'A transição do voto obrigatório para o voto facultativo após os 70 anos é vivenciada a partir de sentimentos conflitantes.', '60+', 'participação e voz', 'voto e acesso à urna', 'achado', 'indício', NULL, '14'), ('D09-TR-084', 'O caráter facultativo da lei é percebido como alívio cívico e conquista de liberdade individual, permitindo o descanso após décadas de cumprimento rigoroso de obrigações eleitorais.', '60+', 'participação e voz', 'voto e acesso à urna', 'achado', 'indício', NULL, '14'), ('D09-TR-085', 'A comodidade do descanso confronta-se diretamente com um sentimento profundo de dever moral, de exercício da cidadania e de participação política construídos ao longo da vida ativa.', '60+', 'participação e voz', 'voto e acesso à urna', 'achado', 'indício', NULL, '15'), ('D09-TR-086', 'Parte dos entrevistados manifesta alívio diante do fim da obrigatoriedade, tomado como licença para o descanso após décadas de cumprimento do dever de votar.', '60+', 'participação e voz', 'voto e acesso à urna', 'achado', 'indício', NULL, '15'), ('D09-TR-088', 'O caráter facultativo do voto funciona como válvula de escape legítima para a frustração e a apatia política acumuladas.', '60+', 'participação e voz', 'voto e acesso à urna', 'achado', 'forte', NULL, '15'), ('D09-TR-089', 'Em oposição à tentação do desinteresse, manifesta-se uma barreira moral sólida e persistente contra o absenteísmo: a autoimagem de cidadão ativo e responsável.', '60+', 'participação e voz', 'voto e acesso à urna', 'achado', 'indício', NULL, '15'), ('D09-TR-090', 'Para parcela significativa dos participantes, o ato de votar é indissociável da dignidade como cidadão e da identidade histórica construída ao longo da vida.', '60+', 'participação e voz', 'voto e acesso à urna', 'achado', 'indício', NULL, '15'), ('D09-TR-095', 'A decisão de ir ou não votar sem imposição legal converte-se em ato consciente e de autoafirmação existencial.', '60+', 'participação e voz', 'voto e acesso à urna', 'achado', 'indício', NULL, '15'), ('D09-TR-096', 'Abdicar do voto é percebido por muitos como equivalente a anular-se socialmente e a admitir que o idoso não serve mais para nada.', '60+', 'participação e voz', 'respeito ao idoso', 'achado', 'indício', NULL, '15'), ('D09-TR-117', 'O ato físico de comparecimento às urnas é diretamente mediado por fatores logísticos e de saúde.', '60+', 'participação e voz', 'voto e acesso à urna', 'achado', 'indício', NULL, '18'), ('D09-TR-118', 'São poucos os idosos que afirmam poder ir votar sozinhos.', '60+', 'participação e voz', 'voto e acesso à urna', 'achado', 'indício', NULL, '18'), ('D09-TR-119', 'A ida às urnas está condicionada à disponibilidade de suporte familiar e de transporte.', '60+', 'participação e voz', 'rede de apoio', 'achado', 'indício', NULL, '18'), ('D09-TR-120', 'Falta de mobilidade, medo de quedas em locais com escadarias e ladeiras e indisponibilidade de acompanhantes são identificados como as principais barreiras que transformam a faculdade do voto em abstenção forçada.', '60+', 'participação e voz', 'moradia e cidade', 'achado', 'indício', NULL, '18'), ('D09-TR-121', 'A autonomia decisória do idoso é intimamente dependente de sua infraestrutura física e familiar.', '60+', 'participação e voz', 'envelhecimento e autonomia', 'achado', 'indício', NULL, '18'), ('D09-TR-122', 'Para idosos com mobilidade reduzida ou que votam em locais distantes, a ida à urna é um processo de negociação familiar.', '60+', 'participação e voz', 'rede de apoio', 'achado', 'indício', NULL, '18'), ('D09-TR-123', 'Muitos dependem do carro de filhos, noras ou genros, o que exige conciliar horários e locais distintos de votação e gera longas esperas para o idoso.', '60+', 'participação e voz', 'rede de apoio', 'achado', 'indício', NULL, '18'), ('D09-TR-124', 'Parte dos idosos depende de transporte por aplicativo financiado pela família para chegar ao local de votação.', '60+', 'participação e voz', 'moradia e cidade', 'achado', 'indício', NULL, '18'), ('D09-TR-125', 'A ausência de suporte logístico familiar é apontada, de forma unânime, como uma das principais causas de abstenção entre os mais velhos.', '60+', 'participação e voz', 'rede de apoio', 'achado', 'forte', NULL, '18'), ('D09-TR-128', 'O discurso familiar de dissuasão é recebido por muitos idosos como forma de desvalorização e exclusão social.', '60+', 'participação e voz', 'respeito ao idoso', 'achado', 'indício', NULL, '18'), ('D09-TR-129', 'Há forte reação de resistência entre idosos que afirmam o desejo de votar justamente como prova de vida, vitalidade e cidadania ativa, recusando a invisibilidade sugerida pelos familiares.', '60+', 'participação e voz', 'respeito ao idoso', 'achado', 'indício', NULL, '18'), ('D09-TR-131', 'Sequelas de quedas, cirurgias ortopédicas recentes, problemas cardiovasculares e doenças crônicas impedem fisicamente a ida desacompanhada às seções eleitorais.', '60+', 'participação e voz', 'voto e acesso à urna', 'achado', 'indício', NULL, '19'), ('D09-TR-132', 'A ausência de rede de apoio e companhia atinge idosos que moram sozinhos ou que são desencorajados por filhos que minimizam a importância do voto não obrigatório, deixando-os sem transporte ou companhia no dia da votação.', '60+', 'participação e voz', 'rede de apoio', 'achado', 'indício', NULL, '19'), ('D09-TR-163', 'Entre os participantes do estudo, o desconhecimento de que os maiores de 70 são 15 milhões de eleitores aptos, dos quais 8 milhões não votaram em 2022, gera espanto e choque moral.', '60+', 'participação e voz', 'participação política', 'achado', 'forte', NULL, '21'), ('D09-TR-164', 'A revelação do peso numérico do voto dos 70+ reverte o sentimento de inutilidade e invisibilidade em percepção de força e orgulho ("70 mais com orgulho").', '60+', 'participação e voz', 'competência e autoestima política', 'achado', 'forte', NULL, '21'), ('D09-TR-166', 'A consciência do peso do voto desperta desejo de atuar como multiplicador: convencer vizinhos, amigos de paróquia, irmãs e parentes idosos a votar.', '60+', 'participação e voz', 'participação política', 'achado', 'forte', NULL, '21'), ('D09-TR-170', 'Para parte dos participantes, o peso numérico não basta: o resultado nulo das propostas em eleições passadas continua a tirar a vontade de votar.', '60+', 'participação e voz', 'promessa e entrega', 'achado', 'indício', NULL, '22'), ('D09-TR-171', 'A motivação mais recorrente para votar é o futuro dos descendentes: filhos, netos e bisnetos importam mais que benefícios individuais.', '60+', 'participação e voz', 'decisão de voto', 'achado', 'forte', NULL, '23'), ('D09-TR-172', 'Na escolha, educação básica, empregos qualificados e segurança pública para filhos e netos assumem o protagonismo; o altruísmo familiar é o elemento mais resistente à abstenção.', '60+', 'participação e voz', 'decisão de voto', 'achado', 'forte', NULL, '23'), ('D09-TR-176', 'A polarização é percebida como ameaça à paz mental, à integridade emocional e à harmonia das relações familiares e sociais.', '60+', 'participação e voz', 'polarização', 'achado', 'forte', NULL, '25'), ('D09-TR-177', 'Para preservar saúde e laços afetivos, os idosos adotam silêncio, neutralidade pública e segredo do voto como escudos; evitar conversa sobre política vira etiqueta de convivência.', '60+', 'participação e voz', 'polarização', 'achado', 'forte', NULL, '25'), ('D09-TR-185', 'Fake news são tema de preocupação e vigilância ativa: os idosos alertam pares e familiares para "ler mais", "não ir na conversa" e evitar páginas suspeitas.', '60+', 'participação e voz', 'informação e desinformação', 'achado', 'forte', NULL, '27'), ('D09-TR-186', 'Os participantes descrevem uma "defesa imunitária" contra discursos fáceis e promessas mirabolantes, apoiada na experiência de vida.', '60+', 'participação e voz', 'promessa e entrega', 'achado', 'forte', NULL, '27'), ('D09-TR-187', 'Muitos relatam usar a análise da fisionomia e da linguagem corporal nos debates como tática para identificar quando alguém está encenando ou mentindo.', '60+', 'participação e voz', 'informação e desinformação', 'achado', 'indício', NULL, '27'), ('D09-TR-192', 'A decisão de voto é afirmada como própria: conversa-se em casa, mas cada um mantém sua escolha.', '60+', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '28'), ('D09-TR-196', 'Votar acompanhado de filhos e netos e reunir a família num almoço festivo ativa utilidade social, inserção comunitária e herança cívica; a festa doméstica é o principal indutor afetivo de comparecimento.', '60+', 'participação e voz', 'voto e acesso à urna', 'achado', 'forte', NULL, '37'), ('D09-TR-200', 'A responsabilidade entre gerações é o principal vetor de ativação do voto facultativo: votar vira rito de amor, proteção familiar e herança ética.', '60+', 'participação e voz', 'decisão de voto', 'achado', 'forte', NULL, '38'), ('D09-TR-203', 'A mensagem que trata da invisibilidade e do descarte social gera orgulho e identificação, sobretudo entre mulheres: a protagonista idosa ativa que recusa ser confinada ou silenciada.', '60+', 'participação e voz', 'competência e autoestima política', 'achado', 'forte', NULL, '39'), ('D09-TR-207', 'Recomendação de voto por artistas, cantores e grandes influenciadores gera ceticismo: fama não se traduz em autoridade política, e o apoio é atribuído a cachês e interesses fiscais.', '60+', 'participação e voz', 'informação e desinformação', 'achado', 'forte', NULL, '40'), ('D09-TR-211', 'Ver um par, "alguém que passa pelas mesmas dificuldades que eu", estimula identificação de classe e pertencimento: o idoso sente sua voz representada.', '60+', 'participação e voz', 'representação política', 'achado', 'forte', NULL, '41'), ('D09-TR-212', 'Figuras públicas como convite ao voto não são rejeitadas, mas não devem substituir a "gente comum".', '60+', 'participação e voz', 'comunicação e linguagem', 'achado', 'indício', NULL, '41'), ('D09-TR-214', 'O diálogo entre avó e neto é avaliado como o recurso de maior impacto para quebrar a inércia do idoso e restabelecer o almoço do dia da eleição como rito cívico.', '60+', 'participação e voz', 'comunicação e linguagem', 'achado', 'forte', NULL, '42'), ('D09-TR-222', 'Sugestões para o dia da eleição: remover barreiras arquitetônicas nos locais de votação, colocar idosos em salas térreas, ampliar filas preferenciais e adequar o acesso para cadeirantes.', '60+', 'participação e voz', 'voto e acesso à urna', 'achado', 'forte', NULL, '46'), ('D09-TR-223', 'A infraestrutura eleitoral divide realidades: seções em bairros estruturados de São Paulo, Teresina e Fortaleza são elogiadas; periferias de Salvador e Recife relatam tumulto, mesários despreparados e falta de guias adaptadas.', '60+', 'participação e voz', 'voto e acesso à urna', 'achado', 'indício', NULL, '47'), ('D09-TR-077', 'A postura de proximidade física e afetiva adotada apenas durante o período de campanha, seguida do afastamento do eleitor comum, é lida como cinismo e alimenta a desilusão.', '60+', 'participação e voz', 'promessa e entrega', 'afasta', NULL, NULL, '13'), ('D09-TR-087', 'O flerte com a abstenção é acentuado pelo cansaço diante de promessas não cumpridas, pela sensação de corrupção generalizada e pela percepção de estagnação nacional de longo prazo.', '60+', 'participação e voz', 'cansaço cívico', 'afasta', NULL, NULL, '15'), ('D09-TR-127', 'A dependência logística de familiares provoca tentativas de filhos e parentes de dissuadir o idoso de votar, com argumentos focados na idade, na perda da obrigatoriedade legal e no desgaste físico desnecessário.', '60+', 'participação e voz', 'voto e acesso à urna', 'afasta', NULL, NULL, '18'), ('D09-TR-133', 'A gratuidade do transporte público em dia de eleição provoca lotações incontornáveis para idosos, que temem ainda os tumultos gerados nos transportes e nos locais de votação.', '60+', 'participação e voz', 'moradia e cidade', 'afasta', NULL, NULL, '19'), ('D09-TR-134', 'Escadarias íngremes, ladeiras e falta de acessibilidade nos colégios eleitorais geram pavor de quedas nos idosos.', '60+', 'participação e voz', 'moradia e cidade', 'afasta', NULL, NULL, '19'), ('D09-TR-135', 'Filas preferenciais congestionadas resultam da delimitação da preferência apenas para eleitores acima de 80 anos em muitos locais de votação.', '60+', 'participação e voz', 'respeito ao idoso', 'afasta', NULL, NULL, '19'), ('D09-TR-136', 'A revolta diante de promessas de campanha sistematicamente descumpridas e o sentimento de descarte social alimentam uma abstenção intencional.', '60+', 'participação e voz', 'cansaço cívico', 'afasta', NULL, NULL, '19'), ('D09-TR-148-par', 'Falar dos 70+ como um bloco único afasta: há idosos ativos e passivos, e a heterogeneidade é a regra.', '60+', 'participação e voz', 'envelhecimento e autonomia', 'afasta', NULL, NULL, '4'), ('D09-TR-149-par', 'Associar velhice a passividade, ao idoso "trancado em uma sala na frente de uma televisão", afasta: para muitos, a mobilização física e social é resistência ao papel de descarte.', '60+', 'participação e voz', 'respeito ao idoso', 'afasta', NULL, NULL, '6'), ('D09-TR-155', 'Mensagem em tom de promessa afasta: "promessa, promessa e nada" é a marca que este público atribui aos políticos e a razão do desânimo.', '60+', 'participação e voz', 'promessa e entrega', 'afasta', NULL, NULL, '13'), ('D09-TR-156', 'Cobrar o voto como obrigação afasta: parte deste público sente alívio com o fim da obrigatoriedade, e o que mobiliza é o voto como direito e prova de vitalidade.', '60+', 'participação e voz', 'voto e acesso à urna', 'afasta', NULL, NULL, '15'), ('D09-TR-157', 'Sugerir que o voto do idoso não faz diferença ou que "pode deixar para os mais jovens" afasta: é lido como descarte, como se "o velho não prestasse mais para nada".', '60+', 'participação e voz', 'voto e acesso à urna', 'afasta', NULL, NULL, '16'), ('D09-TR-178', 'Convocar o idoso a discutir política ou a tomar lado publicamente afasta: debates eleitorais são vistos como brigas que "não servem para nada" e desgastam relações.', '60+', 'participação e voz', 'polarização', 'afasta', NULL, NULL, '25'), ('D09-TR-188', 'Promessas mirabolantes e discursos fáceis afastam: este público se considera imune a eles e confere o que vê no dia a dia, não na propaganda.', '60+', 'participação e voz', 'promessa e entrega', 'afasta', NULL, NULL, '28'), ('D09-TR-194', 'Discursos institucionais rígidos e falas ensaiadas de celebridades afastam: soam sem naturalidade e sem verdade.', '60+', 'participação e voz', 'comunicação e linguagem', 'afasta', NULL, NULL, '37'), ('D09-TR-208', 'Usar celebridades ou grandes influenciadores para convidar ao voto afasta: são vistos como pagos, elitizados e distantes das privações do idoso pobre.', '60+', 'participação e voz', 'comunicação e linguagem', 'afasta', NULL, NULL, '41'), ('D09-TR-209', 'Influenciadores digitais e cultura de memes afastam: falta familiaridade, e são vistos como quem "ganha dinheiro fácil" sem relevância real.', '60+', 'participação e voz', 'comunicação e linguagem', 'afasta', NULL, NULL, '41'), ('D01-TR-001-60', 'Cerca de 4 milhões de eleitores permanecem indecisos para 2026.', '60+', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '6'), ('D01-TR-004-60', 'Entre os votos em aberto, 53% correspondem a mulheres, 32% a jovens de 16 a 34 anos e 23% a pessoas 60+.', '60+', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '8'), ('D01-TR-007-60', '81% dos eleitores do estado de São Paulo não têm escolha definida para o Senado.', '60+', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '8'), ('D01-TR-009', 'O eleitorado 70+ soma 36,2 milhões de pessoas, contingente que cresceu 74% desde 2010, cinco vezes mais que o eleitorado geral, e já representa quase um em cada quatro votos.', '60+', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '11'), ('D01-TR-010', 'O voto é facultativo para maiores de 70 anos; em 2022, 58,9% deles não foram às urnas (8,8 milhões de pessoas). A abstenção vem caindo a cada eleição (era 63,6% em 2014), mas segue extremamente alta.', '60+', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '11'), ('D01-TR-012-60', 'Mulheres representam 52,84% do eleitorado, mais de 83,8 milhões de eleitoras.', '60+', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '13'), ('D01-TR-015-60', 'O voto feminino costuma ser decidido nas semanas finais da campanha, com avaliação por critérios práticos de estabilidade familiar e considerando toda a comunidade, não apenas a própria pessoa.', '60+', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '13'), ('D01-TR-101-60', 'O eleitorado de 16 a 18 anos encolheu 14,5% desde 2022, justamente o grupo que deveria estar entrando no jogo eleitoral.', '60+', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '37'), ('D09-TR-073', 'Viver uma vida longa significa ter atravessado diferentes realidades políticas e vivenciado momentos de esperança e de medo.', '60+', 'participação e voz', 'memória e legado', 'contexto', NULL, NULL, '13'), ('D09-TR-224', 'Os 70+ clamam, ao fim, por reconhecimento de suas limitações e respeito pela trajetória de vida; as barreiras físicas são fator propulsor do absenteísmo.', '60+', 'participação e voz', 'respeito ao idoso', 'contexto', NULL, NULL, '47'), ('D01-TR-144-60', 'Quando a pergunta sobre o Senado é reformulada de forma concreta, associando-o a salário, escala de trabalho e direitos, o tom muda de indiferença para indignação.', '60+', 'participação e voz', 'funcionamento do legislativo', 'funciona', NULL, NULL, '55'), ('D01-TR-147-60', 'A comunicação sobre o Legislativo não precisa começar pelo Senado, precisa começar pelo problema: escala 6x1, salário, transporte, segurança e segurança digital.', '60+', 'participação e voz', 'funcionamento do legislativo', 'funciona', NULL, NULL, '55'), ('D09-TR-091', 'O comparecimento às urnas é descrito com orgulho e prazer, considerado não uma obrigação, mas um direito soberano conquistado que deve ser exercido com honra e vaidade.', '60+', 'participação e voz', 'voto e acesso à urna', 'funciona', NULL, NULL, '15'), ('D09-TR-092', 'O ritual de arrumar-se para o dia da votação é acionado como componente de prazer e afirmação pessoal no comparecimento.', '60+', 'participação e voz', 'voto e acesso à urna', 'funciona', NULL, NULL, '15'), ('D09-TR-093', 'O voto voluntário é defendido como dever moral insubstituível para fazer a própria parte, garantindo legitimidade para cobrar melhorias dos governantes eleitos.', '60+', 'participação e voz', 'voto e acesso à urna', 'funciona', NULL, NULL, '15'), ('D09-TR-097', 'Comparecer voluntariamente às urnas é visto como ato de resistência e afirmação de que a idade não retira a validade da voz nem das demandas no país.', '60+', 'participação e voz', 'respeito ao idoso', 'funciona', NULL, NULL, '15'), ('D09-TR-101', 'O voto converte-se em mecanismo de defesa contra o isolamento social.', '60+', 'participação e voz', 'respeito ao idoso', 'funciona', NULL, NULL, '16'), ('D09-TR-126', 'Quando a família se mobiliza e vota no mesmo local, o dia da eleição é ressignificado como momento de confraternização e almoço familiar, o que fortalece o desejo de comparecimento.', '60+', 'participação e voz', 'voto e acesso à urna', 'funciona', NULL, NULL, '18'), ('D09-TR-130', 'Há também laços familiares positivos de incentivo intergeracional, nos quais netos e filhos motivam os idosos a votar como parte de um legado familiar para o futuro do país.', '60+', 'participação e voz', 'memória e legado', 'funciona', NULL, NULL, '18'), ('D09-TR-165', 'Informar o peso do voto dos maiores de 70, quantos são e quantos deixaram de votar, mobiliza: idosas indecisas ou desanimadas relatam vontade imediata de votar.', '60+', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '21'), ('D09-TR-167', 'Convidar o idoso a ser multiplicador ("vamos arrastar todo mundo", "fazer a propaganda boca a boca") aproxima: o voto passa a ser defendido como solidariedade entre gerações.', '60+', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '22'), ('D09-TR-173', 'Apresentar o voto como investimento no futuro dos filhos e netos aproxima: para este público, educação, emprego e segurança para as gerações mais jovens valem mais que vantagens próprias.', '60+', 'participação e voz', 'decisão de voto', 'funciona', NULL, NULL, '23'), ('D09-TR-193', 'Formato narrativo de "historinha" conjugal curta, leve e bem-humorada aproxima: um diálogo cotidiano entre marido e mulher transmite mais naturalidade e verdade que discurso institucional.', '60+', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '37'), ('D09-TR-195', 'Esclarecer que existe fila preferencial a que o idoso tem direito funciona como argumento decisivo: saber que "passa na frente" converte receio de desgaste em disposição para votar.', '60+', 'participação e voz', 'voto e acesso à urna', 'funciona', NULL, NULL, '37'), ('D09-TR-197', 'Associar o dia da eleição a um encontro familiar, o almoço ou a feijoada depois de votar, aproxima: comida e festa doméstica são os principais indutores afetivos do comparecimento.', '60+', 'participação e voz', 'voto e acesso à urna', 'funciona', NULL, NULL, '37'), ('D09-TR-204', 'Mostrar uma idosa ativa, bem arrumada e que recusa ser silenciada aproxima: "a gente com 70 anos não está tão acabadinha".', '60+', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '39'), ('D09-TR-210', 'Depoimentos de pessoas comuns e anônimas aproximam: fisionomias marcadas pelo tempo, cabelos brancos naturais, roupas simples e cenários domésticos reais transmitem honestidade e verdade.', '60+', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '41'), ('D09-TR-213', 'O formato de uma avó conversando espontaneamente com o neto gera identificação afetiva imediata: une a experiência acumulada da avó à perspectiva de futuro do neto.', '60+', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '42'), ('D09-TR-027', '"Eu tenho 70 mas eu não me sinto com uma pessoa de 70. Eu me sinto como 40, 50."', '60+', 'participação e voz', 'envelhecimento e autonomia', 'verbatim', NULL, NULL, '7'), ('D09-TR-058', '"Eu conversava muito mais, era o meu marido, porque ele falava direto de política, aí a gente conversava. Agora eu não tenho mais, não converso mais com ninguém."', '60+', 'participação e voz', 'saúde mental', 'verbatim', NULL, NULL, '10'), ('D09-TR-067', '"Eu gostaria de ser reconhecida pelos poderes públicos. Um plano de saúde a gente não pode pagar. Mas eu gostaria que os políticos criassem uma situação para a gente, idosos, ter uma vida melhor."', '60+', 'participação e voz', 'respeito ao idoso', 'verbatim', NULL, NULL, '12'), ('D09-TR-080', '"Eu penso que eles vêm, prometem um rio de coisas... chega na hora, estão lá bem instaladinhos e nada fazem. Para mim é tudo farinha do mesmo saco."', '60+', 'participação e voz', 'promessa e entrega', 'verbatim', NULL, NULL, '13'), ('D09-TR-081', '"Eles prometem tudo, abraça todo mundo, vai lá no meio do público abraçar todo mundo e todo mundo confia. Só que depois que passa tudo isso, vai procurar um deles? Eles não conhecem a gente."', '60+', 'participação e voz', 'promessa e entrega', 'verbatim', NULL, NULL, '13'), ('D09-TR-082', '"Os velhos já estão revoltados, porque todos que entram não fazem nada. O tempo passa e é sempre a mesma coisa. E ouço eles falarem a mesma coisa desde que era jovem."', '60+', 'participação e voz', 'cansaço cívico', 'verbatim', NULL, NULL, '13'), ('D09-TR-094', '"Se a gente não vota, depois não pode reclamar."', '60+', 'participação e voz', 'voto e acesso à urna', 'verbatim', NULL, NULL, '15'), ('D09-TR-100', '"Não é porque passei dos 70 que perdi minha validade."', '60+', 'participação e voz', 'respeito ao idoso', 'verbatim', NULL, NULL, '16'), ('D09-TR-102', '"Eu acho para fazer meus direitos, para poder fazer os direitos da gente, o meu, o dos outros. E é importante a gente votar, para também lembrar que a gente tem... a idade não diz nada."', '60+', 'participação e voz', 'voto e acesso à urna', 'verbatim', NULL, NULL, '16'), ('D09-TR-103', '"Eu já votei tanto por obrigação, que hoje que eu não tenho mais obrigação, eu já não estou me incomodando mais porque eu não vejo diferença."', '60+', 'participação e voz', 'cansaço cívico', 'verbatim', NULL, NULL, '16'), ('D09-TR-104', '"Eu acho que eu não vou votar também. Eu não sei por que, mas acho que já votei bastante e não muda muita coisa. Então tô achando que o meu voto não vai fazer muita diferença não."', '60+', 'participação e voz', 'cansaço cívico', 'verbatim', NULL, NULL, '16'), ('D09-TR-105', '"Nós fomos obrigados a votar até os 70 anos. Aí você chega nessa idade, você fala: ''Dane-se! Não quero mais, já deu!''. Por quê? Porque não muda."', '60+', 'participação e voz', 'cansaço cívico', 'verbatim', NULL, NULL, '16'), ('D09-TR-106', '"A minha dúvida é isso aí. É que eu acho que, com a idade que eu tenho hoje, eu acho que o meu voto não vai importar para nada. Ele não vai fazer diferença."', '60+', 'participação e voz', 'cansaço cívico', 'verbatim', NULL, NULL, '16'), ('D09-TR-107', '"Minha dificuldade, que eu acho assim que é ruim, é as promessas dos políticos, dos prefeitos, do governo, que falam e não cumprem. Tantas vezes que eu fui: promessa, promessa, promessa, e só faz prometer."', '60+', 'participação e voz', 'promessa e entrega', 'verbatim', NULL, NULL, '16'), ('D09-TR-109', '"Aqui na minha rua tem umas três que não vai votar não, não tem mais obrigação de votar, não tem mais idade... Mas não vai votar em ninguém porque ninguém dá nada a ela."', '60+', 'participação e voz', 'cansaço cívico', 'verbatim', NULL, NULL, '17'), ('D09-TR-110', '"A gente até acha que pela idade não tem mais valor. E tem valor igual ao outro, o peso, o valor do voto é o mesmo. A gente tem vontade de ir, mas nossos filhos dizem: ''não vai, para quê? Teu voto não precisa mais''."', '60+', 'participação e voz', 'voto e acesso à urna', 'verbatim', NULL, NULL, '17'), ('D09-TR-111', '"Talvez. Mas eu gosto muito de votar. Agora, como minha idade já está avançada, eu posso deixar para os mais jovens, não é isso?"', '60+', 'participação e voz', 'voto e acesso à urna', 'verbatim', NULL, NULL, '17'), ('D09-TR-112', '"Não! É um dia de festa! É um dia de festa para o Brasil! Todo mundo se arruma para sair de casa para ir votar."', '60+', 'participação e voz', 'voto e acesso à urna', 'verbatim', NULL, NULL, '17'), ('D09-TR-113', '"Vou cumprir meu direito civil de votar, porque aí eu vou votar e não tenho o que reclamar porque fui eu que escolhi a pessoa."', '60+', 'participação e voz', 'voto e acesso à urna', 'verbatim', NULL, NULL, '17'), ('D09-TR-114', '"Porque nós temos que ter a consciência de um dever cumprido. Porque nós precisamos de segurança, nós precisamos de saúde, nós precisamos de educação."', '60+', 'participação e voz', 'voto e acesso à urna', 'verbatim', NULL, NULL, '17'), ('D09-TR-115', '"A gente tem que votar porque é um direito que a gente tem de exercer a nossa cidadania. E eu gosto de sair de casa, não gosto de ficar preso dentro de casa. Então vou aproveitar essa oportunidade para sair para ir votar."', '60+', 'participação e voz', 'voto e acesso à urna', 'verbatim', NULL, NULL, '17'), ('D09-TR-137', '"Vai depender da minha filha vir me pegar para levar. Porque eu voto longe, não voto perto da minha casa, então eu preciso que ela venha me pegar para levar para votar."', '60+', 'participação e voz', 'rede de apoio', 'verbatim', NULL, NULL, '19'), ('D09-TR-138', '"Eu vou com meu filho porque ele vota no mesmo colégio e é aqui perto da minha casa. Então a gente sempre vota junto aqui."', '60+', 'participação e voz', 'rede de apoio', 'verbatim', NULL, NULL, '19'), ('D09-TR-139', '"Para mim é difícil de ir votar porque eu dependo de uma pessoa para ir comigo e eu não tenho devido eu morar sozinha."', '60+', 'participação e voz', 'rede de apoio', 'verbatim', NULL, NULL, '19'), ('D09-TR-140', '"A minha dificuldade para ir votar é porque dependo também de filho. E às vezes fica... um vota em um local, outro vota em outro local, aí fica aquela dificuldade: leva um, leva outro. E por causa também da minha falta de equilíbrio para caminhar."', '60+', 'participação e voz', 'rede de apoio', 'verbatim', NULL, NULL, '19'), ('D09-TR-141', '"Pretendo ir votar, mas eu acho bom ir com as minhas irmãs, a gente se reúne tudinho. Elas votam no mesmo canto que eu, aí preciso da ajuda delas. Se elas não forem, eu não vou. Sou cadeirante."', '60+', 'participação e voz', 'moradia e cidade', 'verbatim', NULL, NULL, '20'), ('D09-TR-142', '"Por não ser obrigado, aos poucos vai perdendo aquele estímulo de votar, até a própria família: ''ah papai ou mamãe, não é mais obrigado você votar''. Aí aquilo vai criando na cabecinha da gente."', '60+', 'participação e voz', 'voto e acesso à urna', 'verbatim', NULL, NULL, '20'), ('D09-TR-143', '"Às vezes a gente quer votar e nosso filho diz: ''não vota, para quê? Fica em casa''."', '60+', 'participação e voz', 'voto e acesso à urna', 'verbatim', NULL, NULL, '20'), ('D09-TR-144', '"Me dizem: ''Precisa mais não, mãinha, que a senhora já tá numa idade que pra que a senhora vai votar? Aí a senhora nem paga multa se não for''. Aí eu disse: ''Mas eu gosto!''. Eu gosto de ir, de me arrumar nesse dia, eu arrumo, boto meu ajeitado no cabelo, boto um batonzinho e vou muito bem votar."', '60+', 'participação e voz', 'voto e acesso à urna', 'verbatim', NULL, NULL, '20'), ('D09-TR-145', '"Eu pretendo ir votar se tiver alguém que me acompanhe, porque eu estou com um problemazinho de osso, não subo mais assim em ônibus tranquilamente."', '60+', 'participação e voz', 'rede de apoio', 'verbatim', NULL, NULL, '20'), ('D09-TR-146', '"E muitas vezes o próprio local onde você vai votar é distante da sua casa porque às vezes eles colocam bem distante. E aí você, por essa idade, você já não vai sozinha. Então depende que um filho leve."', '60+', 'participação e voz', 'voto e acesso à urna', 'verbatim', NULL, NULL, '20'), ('D09-TR-147', '"Porque a gente tem que pensar nos filhos da gente, nos netos, que estão crescendo. A gente não pode nem sair no portão. Então a gente tem que ver direitinho e pesquisar para ver o que é melhor para nós."', '60+', 'participação e voz', 'memória e legado', 'verbatim', NULL, NULL, '20'), ('D09-TR-162', 'Eu gosto de ir, de me arrumar nesse dia, eu arrumo, boto meu ajeitado no cabelo, boto um batonzinho e vou muito bem votar.', '60+', 'participação e voz', 'voto e acesso à urna', 'verbatim', NULL, NULL, '20'), ('D09-TR-168', 'Nós estamos vivos, nós estamos vivendo aqui e nós somos cidadãos brasileiros. Então a gente tem que tomar posse disso e ir lá nas urnas mostrar para o povo que a gente também tem opinião.', '60+', 'participação e voz', 'competência e autoestima política', 'verbatim', NULL, NULL, '22'), ('D09-TR-169', 'Nossa, olha nós aí. Nós somos a força ainda.', '60+', 'participação e voz', 'competência e autoestima política', 'verbatim', NULL, NULL, '22'), ('D09-TR-174', 'Eu penso assim: para meus filhos, para meus netos tem que ser melhor. Melhor para eles do que para mim.', '60+', 'participação e voz', 'decisão de voto', 'verbatim', NULL, NULL, '24'), ('D09-TR-175', 'Meu filho, eu que já estou nessa idade não preciso votar e vou votar... você está novo, precisa trabalhar, precisa d''um emprego, então você tem que votar.', '60+', 'participação e voz', 'voto e acesso à urna', 'verbatim', NULL, NULL, '24'), ('D09-TR-179', 'Eu deixo todo mundo feliz. ''Você vai votar em fulano?'' ''Vou''. ''Vai votar nesse?'' ''Vou''. O voto é secreto, não é secreto?', '60+', 'participação e voz', 'polarização', 'verbatim', NULL, NULL, '26'), ('D09-TR-180', 'Política, religião, mulher e futebol não se discute. Você pode falar, agora não se discute.', '60+', 'participação e voz', 'polarização', 'verbatim', NULL, NULL, '26'), ('D09-TR-189', 'A gente vê quando está mentindo pela fisionomia, a gente já sabe que está mentindo. Não vou perder um debate.', '60+', 'participação e voz', 'informação e desinformação', 'verbatim', NULL, NULL, '28'), ('D09-TR-190', 'Muitos fazem propaganda, mas não cumprem nem a metade do que eles prometem a gente. Então é melhor a gente ver no dia a dia.', '60+', 'participação e voz', 'promessa e entrega', 'verbatim', NULL, NULL, '28'), ('D09-TR-191', 'Eu não sou muito boa de telefone, de computador, parece que é um bicho que vai me comer.', '60+', 'participação e voz', 'informação e desinformação', 'verbatim', NULL, NULL, '28'), ('D09-TR-198', 'Eu sofro muito isso: ''Ah não, a senhora não tem 80 ainda''. Falo: ''Mas gente, eu tenho 70, o que que falta para 80?''', '60+', 'participação e voz', 'voto e acesso à urna', 'verbatim', NULL, NULL, '38'), ('D09-TR-199', 'Vamos fazer uma feijoada aí para comemorar essas eleições, não é isso? Entre família.', '60+', 'participação e voz', 'voto e acesso à urna', 'verbatim', NULL, NULL, '38'), ('D09-TR-205', 'Mostra que a família da gente às vezes diz ''ah você está velha, não serve mais para nada'' e o vídeo mostra o valor da gente.', '60+', 'participação e voz', 'competência e autoestima política', 'verbatim', NULL, NULL, '40'), ('D09-TR-206', 'Porque ficou idoso não é que deixou de ser cidadão, não é isso?', '60+', 'participação e voz', 'competência e autoestima política', 'verbatim', NULL, NULL, '40'), ('D09-TR-215', 'O famoso ele pode ser muito direcionado. Pode ganhar bem de A ou B.', '60+', 'participação e voz', 'comunicação e linguagem', 'verbatim', NULL, NULL, '42'), ('D09-TR-216', 'É porque gente comum está mais perto da nossa realidade, o famoso já está num nível mais elevado.', '60+', 'participação e voz', 'comunicação e linguagem', 'verbatim', NULL, NULL, '42'), ('D09-TR-001', 'Os cidadãos com mais de 70 anos não constituem um bloco homogêneo, ainda que compartilhem momentos históricos e estágios de vida semelhantes.', '60+', NULL, 'envelhecimento e autonomia', 'perfil', NULL, NULL, '4'), ('D09-TR-002', 'Variáveis regionais, nível socioeconômico, vida profissional pregressa, estrutura familiar e acesso à educação incidem sobre o comportamento e o modo de pensar nessa faixa etária.', '60+', NULL, 'envelhecimento e autonomia', 'perfil', NULL, NULL, '4'), ('D09-TR-004', 'Mulheres tendem a apresentar perfil mais ativo e disposição mais positiva do que homens nessa faixa etária.', '60+', NULL, 'envelhecimento e autonomia', 'perfil', NULL, NULL, '4'), ('D09-TR-006', 'Chegar e ultrapassar os 70 anos é vivenciado como vitória, em contexto de convivência frequente com a morte de cônjuges, amigos e familiares.', '60+', NULL, 'envelhecimento e autonomia', 'perfil', NULL, NULL, '5'), ('D09-TR-007', 'As perdas de pessoas próximas, além do sofrimento, consolidam a percepção de que estar vivo e lúcido já é motivo de grande contentamento.', '60+', NULL, 'envelhecimento e autonomia', 'perfil', NULL, NULL, '5'), ('D09-TR-011', 'Parte dos entrevistados compõe um subgrupo de idosos altamente ativos que recusa a postura passiva diante do envelhecimento e se descreve como jovem de espírito.', '60+', NULL, 'envelhecimento e autonomia', 'perfil', NULL, NULL, '5'), ('D09-TR-012', 'Entre os participantes deste estudo, a prática de atividades corporais é amplamente disseminada e defendida, associando a movimentação física direta à saúde mental e ao combate à depressão.', '60+', NULL, 'envelhecimento e autonomia', 'perfil', NULL, NULL, '5'), ('D09-TR-013', 'Academia, musculação, alongamento, pilates, ginástica e hidroginástica figuram como rotinas consolidadas entre os idosos mais ativos.', '60+', NULL, 'envelhecimento e autonomia', 'perfil', NULL, NULL, '5'), ('D09-TR-014', 'Atividades mais vigorosas, como aulas de dança e ciclismo de longa distância, aparecem como formas expressivas de vivacidade e de inserção cultural e social.', '60+', NULL, 'cultura e lazer', 'perfil', NULL, NULL, '5'), ('D09-TR-015', 'A caminhada ao ar livre, acompanhada por familiares, vizinhos ou animais de estimação, é a atividade física mais acessível e é descrita como hábito revigorante diário.', '60+', NULL, 'envelhecimento e autonomia', 'perfil', NULL, NULL, '6'), ('D09-TR-016', 'Trabalhos manuais e lazer produtivo, como artesanato, crochê e patchwork, são descritos como hobbies significativos para manter a mente ativa, com referências sobretudo entre mulheres.', '60+', NULL, 'cultura e lazer', 'perfil', NULL, NULL, '6'), ('D09-TR-018', 'Atividades paroquiais e passeios promovidos por igrejas evangélicas e católicas integram a rotina social do segmento.', '60+', NULL, 'fé e religiosidade', 'perfil', NULL, NULL, '6'), ('D09-TR-019', 'Cursos gratuitos de informática e projetos educacionais e de lazer voltados à terceira idade, como universidades abertas mantidas por instituições públicas, aparecem pontualmente como espaços de participação.', '60+', NULL, 'cultura e lazer', 'perfil', NULL, NULL, '6'), ('D09-TR-020', 'Sair de casa, frequentar academias e encontrar amigos e vizinhos é diretamente associado ao bem-estar mental, que por sua vez estimula o vigor físico.', '60+', NULL, 'envelhecimento e autonomia', 'perfil', NULL, NULL, '6'), ('D09-TR-021', 'A mobilização física e social funciona como resistência psicológica à aceitação do papel de descarte e do confinamento doméstico diante da televisão.', '60+', NULL, 'envelhecimento e autonomia', 'perfil', NULL, NULL, '6'), ('D09-TR-022', 'Entre os participantes deste estudo, na maior parte dos casos de forma involuntária, há um segundo segmento definido pela passividade decorrente de limitações físicas impostas por doenças leves, moderadas ou agudas, temporárias ou permanentes.', '60+', NULL, 'saúde e sus', 'perfil', NULL, NULL, '6'), ('D09-TR-023', 'A saúde é percebida como a maior riqueza da terceira idade e sua perda como o maior desafio à própria existência.', '60+', NULL, 'saúde e sus', 'perfil', NULL, NULL, '7'), ('D09-TR-026', 'A presença de condição física limitante está na raiz do sentimento de perda de autonomia e de dependência de terceiros para qualquer atividade fora de casa.', '60+', NULL, 'envelhecimento e autonomia', 'perfil', NULL, NULL, '7'), ('D09-TR-034', 'Além das limitações de saúde, há dores emocionais provocadas pela tensão entre superproteção familiar e autonomia individual.', '60+', NULL, 'rede de apoio', 'perfil', NULL, NULL, '9'), ('D09-TR-035', 'Há padrão comportamental recorrente de imposição de limites à liberdade física dos idosos por parte dos filhos, justificada como cuidado ou preocupação.', '60+', NULL, 'rede de apoio', 'perfil', NULL, NULL, '9'), ('D09-TR-036', 'Mulheres relatam com mais frequência serem desencorajadas a realizar atividades simples do cotidiano desacompanhadas, como ir à padaria ou atravessar a rua.', '60+', NULL, 'rede de apoio', 'perfil', NULL, NULL, '9'), ('D09-TR-037', 'Embora o afeto contido nessa vigilância seja reconhecido e por vezes tomado como prova de amor, muitos relatos registram sentimento de limitação e perda de espontaneidade.', '60+', NULL, 'rede de apoio', 'perfil', NULL, NULL, '9'), ('D09-TR-038', 'A estrutura habitacional é fator determinante na delimitação do comportamento dos idosos, que se distribuem entre morar com cônjuge, com filhos, com netos ou sozinhos.', '60+', NULL, 'moradia e cidade', 'perfil', NULL, NULL, '9'), ('D09-TR-039', 'Quem mora com outros membros da família se sente mais amparado, porém mais limitado e vigiado.', '60+', NULL, 'moradia e cidade', 'perfil', NULL, NULL, '9'), ('D09-TR-040', 'Quem mora sozinho, por viuvez ou por saída dos filhos de casa, demonstra mais independência, mas também amargura e nostalgia do período em que a família estava reunida.', '60+', NULL, 'moradia e cidade', 'perfil', NULL, NULL, '9'), ('D09-TR-065', 'Na percepção dos idosos, o que falta à sociedade é respeito e reconhecimento por aqueles que dedicaram a vida ao trabalho e ao sustento da família e contribuíram para o desenvolvimento do país.', '60+', NULL, 'reconhecimento do trabalho', 'perfil', NULL, NULL, '12'), ('D09-TR-181', 'A televisão é o canal de informação mais consolidado e confiável para este público: telejornais locais e nacionais e programas de variedades marcam a atualização cotidiana.', '60+', NULL, NULL, 'perfil', NULL, NULL, '26'), ('D09-TR-182', 'Em período eleitoral, os debates televisivos ganham centralidade absoluta: são o principal espaço de validação das propostas, assistidos de forma concentrada e sem intermediários.', '60+', NULL, NULL, 'perfil', NULL, NULL, '26'), ('D09-TR-183', 'A adesão às mídias digitais é heterogênea: parte consome notícias e entretenimento por YouTube, WhatsApp, Facebook e Instagram, com casos de TikTok e Kwai; outra parte relata exclusão digital e depende de filhos e netos para acessar e checar informação.', '60+', NULL, NULL, 'perfil', NULL, NULL, '27'), ('D09-TR-184', 'O YouTube é valorizado como biblioteca visual de reportagens e vídeos informativos.', '60+', NULL, NULL, 'perfil', NULL, NULL, '27'), ('D01-TR-029', 'Dinheiro no bolso ainda é sentido como sonho distante, mas o desejo por mais que sobreviver não desaparece: há vontade de ter coisas e de melhores condições de vida.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '17'), ('D01-TR-031', 'O Bolsa Família entra no planejamento da casa antes mesmo de ser discutido como política pública; o que sustenta isso não é só o valor, é a previsibilidade de saber que o dinheiro vai cair.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '18'), ('D01-TR-032', 'O benefício já é visto como direito, mas nunca foi suficiente; o desejo de mais que sobreviver vira alvo de acusação de ingratidão.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '18'), ('D01-TR-042-mb', 'O dinheiro aparece como falta ou sonho distante, mas deve ser narrado como retomada de controle.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '20'), ('D01-TR-052-mb', 'A equação tempo igual a dinheiro pesa no cotidiano.', 'mulheres beneficiárias', 'dinheiro no bolso', 'jornada de trabalho', 'achado', 'indício', NULL, '22'), ('D03-TR-002', '22,9% da população declara ser beneficiária de algum programa do governo federal. O Bolsa Família é o mais citado (11,3%), seguido da aposentadoria (7,9%) e do BPC/LOAS (1,3%).', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '13'), ('D03-TR-003', 'A presença de beneficiários de programas federais varia por região: 35,1% no Nordeste e 26,2% no Norte, contra 16,6% no Sudeste, 16,9% no Centro-Oeste e 19,0% no Sul.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '13'), ('D03-TR-006-mb', '5,4% da população obteve renda nos últimos doze meses com alguma atividade online, como vendas, links de afiliados, revendas, visualização remunerada de vídeos ou atuação como ponto de coleta de lojas online.', 'mulheres beneficiárias', 'dinheiro no bolso', 'renda e sustento', 'achado', 'indício', NULL, '15'), ('D03-TR-066', 'Na avaliação da gestão federal por área, programas sociais de modo geral têm a melhor avaliação: 36,5% ótima ou boa, 35,3% regular e 21,6% ruim ou péssima.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '73'), ('D03-TR-074-mb', 'O combate às desigualdades e privilégios recebe 21,1% de avaliação ótima ou boa e 38,2% ruim ou péssima.', 'mulheres beneficiárias', 'dinheiro no bolso', 'desigualdade', 'achado', 'indício', NULL, '73'), ('D03-TR-075-mb', 'Custo de vida, poder de compra e economia é a área com pior avaliação da gestão federal: 16,0% ótima ou boa e 53,7% ruim ou péssima.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '73'), ('D03-TR-078', 'O Novo Bolsa Família, com mais 150 reais por criança, é conhecido por 77,4%; a avaliação é 54,4% ótima ou boa, 20,2% regular e 19,4% ruim ou péssima.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '76'), ('D03-TR-080-mb', 'A isenção do Imposto de Renda para quem ganha até 5 mil reais é conhecida por 72,4%, com avaliação de 68,9% ótima ou boa e 11,4% ruim ou péssima.', 'mulheres beneficiárias', 'dinheiro no bolso', 'impostos', 'achado', 'indício', NULL, '76'), ('D03-TR-082', 'O Gás do Povo é conhecido por 62,7%, com avaliação de 59,2% ótima ou boa e 18,4% ruim ou péssima.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '76'), ('D03-TR-083-mb', 'O Desenrola, para renegociar dívidas, é conhecido por 62,1%, com avaliação de 67,9% ótima ou boa e 9,7% ruim ou péssima.', 'mulheres beneficiárias', 'dinheiro no bolso', 'endividamento e crédito', 'achado', 'indício', NULL, '76'), ('D03-TR-086', 'O Luz do Povo é conhecido por 48,3%, com avaliação de 59,6% ótima ou boa e 18,6% ruim ou péssima.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '76'), ('D03-TR-088', 'O conhecimento e a avaliação do Novo Bolsa Família são maiores no Nordeste (83,9% conhecem; 65,3% ótima ou boa) do que no Sudeste (74,6% conhecem; 48,6% ótima ou boa).', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '78'), ('D03-TR-089-mb', 'No Nordeste, o Pé-de-Meia é o programa federal mais conhecido da lista (90,1%), acima da média nacional (81,0%), com avaliação de 69,3% ótima ou boa.', 'mulheres beneficiárias', 'dinheiro no bolso', 'educação', 'achado', 'indício', NULL, '78'), ('D07-TR-001-mb', 'Entre os participantes deste estudo, custo de vida, poder de compra e economia é a área de maior peso na formação da avaliação pública de desempenho governamental.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '3'), ('D07-TR-018-mb', 'Custo de vida concentra o maior impacto isolado sobre a avaliação pública de desempenho, com magnitude cerca de duas vezes a da segunda área da lista.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '5'), ('D07-TR-028-mb', 'Na Região Sul, o peso de custo de vida na avaliação de desempenho governamental é substancialmente superior ao observado no conjunto do país.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '6'), ('D07-TR-045-mb', 'Na Região Norte, o peso de custo de vida na avaliação de desempenho governamental é substancialmente superior ao observado no conjunto do país.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '10'), ('D10-TR-020', 'Na macronarrativa de dinheiro no bolso, a narrativa central vai do aperto ao controle possível sobre o mês.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação e linguagem', 'achado', 'indício', NULL, '8'), ('D10-TR-021', 'A transformação semiótica do dinheiro no bolso vai da disjunção com estabilidade, escolha e previsibilidade para a conjunção com competências de organização, priorização e domínio mínimo sobre o mês.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação e linguagem', 'achado', 'indício', NULL, '8'), ('D10-TR-157', 'Dinheiro no bolso é lido pela régua da casa: comida, gás, luz, água, remédio, escola, transporte, cartão e contas do mês.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '32'), ('D10-TR-158', 'O programa de transferência de renda não gera sobra, mas organiza o orçamento, reduz risco e ajuda a planejar.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '32'), ('D10-TR-159', 'O benefício pode funcionar como sobrevivência, como complemento ou como respiro, conforme a situação da casa.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '32'), ('D10-TR-160', 'A confiança depende de realismo: qualquer melhora convive com custo alto, imprevistos e baixa margem.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '32'), ('D10-TR-161', 'Nas redes, o dinheiro aparece pela falta: salário que some, conta que não fecha, dívida, inflação no mercado e sensação de perda de controle.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '32'), ('D10-TR-162', 'O benefício está em disputa na conversa digital: críticos falam em dependência, enquanto beneficiárias mostram que ajuda, mas não garante luxo nem resolve tudo.', 'mulheres beneficiárias', 'dinheiro no bolso', 'estigma do benefício', 'achado', 'indício', NULL, '32'), ('D10-TR-163', 'O alívio prometido pelo benefício esbarra em falhas de acesso, dúvidas de calendário, aplicativo instável, burocracia e custos extras.', 'mulheres beneficiárias', 'dinheiro no bolso', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '32'), ('D10-TR-169', 'Estigma e disputa moral formam uma isotopia recorrente: o uso do benefício vira julgamento sobre merecimento.', 'mulheres beneficiárias', 'dinheiro no bolso', 'estigma do benefício', 'achado', 'indício', NULL, '34'), ('D10-TR-170', 'O programa de transferência de renda é atravessado por julgamentos sobre trabalho, merecimento, dependência e mau uso do dinheiro.', 'mulheres beneficiárias', 'dinheiro no bolso', 'estigma do benefício', 'achado', 'indício', NULL, '34'), ('D10-TR-172', 'Falta e aperto formam uma isotopia recorrente: o dinheiro chega, mas já nasce comprometido.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '34'), ('D10-TR-173', 'O dinheiro é percebido pela ausência: não sobra, some rápido, chega comprometido e não fecha o mês.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '34'), ('D10-TR-175', 'Controle e organização formam uma isotopia recorrente: é quando se recupera algum domínio sobre o mês.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '34'), ('D10-TR-176', 'O benefício ganha valor quando permite ordenar prioridades, reduzir risco e segurar o básico da casa.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '34'), ('D10-TR-178', 'Respiro e possibilidade formam uma isotopia recorrente: é quando o dinheiro permite sair do sufoco imediato.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '34'), ('D10-TR-179', 'O alívio não é luxo: é a chance de respirar, escolher melhor, pagar algo, sair do sufoco e fazer algum plano.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '34'), ('D10-TR-184', 'No estado inicial, a mulher aparece em disjunção com os objetos de valor que organizam uma vida minimamente estável: comida suficiente, contas pagas, gás garantido, remédio, crédito sem vergonha, previsibilidade e capacidade de escolha.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação e linguagem', 'achado', 'indício', NULL, '35'), ('D10-TR-185', 'Nesse estado inicial, a mulher está modalizada sobretudo pelo dever fazer e pelo ter que dar conta: precisa sustentar a casa, priorizar despesas, evitar faltar e proteger os filhos, mesmo sem margem real de ação.', 'mulheres beneficiárias', 'dinheiro no bolso', 'cuidado e sobrecarga', 'achado', 'indício', NULL, '35'), ('D10-TR-186', 'Na dimensão eufórica do controle, a narrativa desloca a mulher para a conjunção com competências que ampliam seu poder fazer: organizar o orçamento, decidir prioridades, quitar ou evitar dívidas, reservar o gás, completar a feira, pagar uma conta, comprar algo para os filhos e planejar o próximo passo.', 'mulheres beneficiárias', 'dinheiro no bolso', 'participação política', 'achado', 'indício', NULL, '35'), ('D10-TR-187', 'O objeto de valor não é ter dinheiro sobrando, mas recuperar domínio mínimo sobre o mês.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação e linguagem', 'achado', 'indício', NULL, '35'), ('D11-TR-005', 'O benefício é vivido como estrutura da casa: organiza o orçamento, reduz risco e dá previsibilidade.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '8'), ('D11-TR-014', 'Qualquer melhora é avaliada pela capacidade real de reduzir pressão no cotidiano.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '11'), ('D11-TR-017', 'A percepção econômica é doméstica e concreta: melhorou significa conseguir fazer mercado, pagar contas, comprar gás, resolver uma consulta, garantir material escolar ou chegar menos apertada ao fim do mês, e não acreditar que a economia do país vai bem.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '11'), ('D11-TR-019', 'A comparação com quatro ou cinco anos atrás não é linear: avanços pontuais em benefícios, renda, trabalho ou serviços convivem com custo de vida alto, insegurança e sensação de que a vida ainda exige controle permanente.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '11'), ('D11-TR-040', 'A melhora é medida no mercado e nas contas, não pela linguagem da macroeconomia, mas pela possibilidade de comprar comida, pagar luz, gás, água, aluguel, transporte, remédio, escola e cartão.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '14'), ('D11-TR-041', 'O aperto aparece como sequência de encaixes: mesmo quando há renda, benefício ou trabalho, o dinheiro chega com destino definido, o que reduz a sensação de autonomia e mantém a vida em cálculo permanente.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '14'), ('D11-TR-042', 'Pequenos imprevistos têm efeito desproporcional: um exame, uma condução, um lanche de escola, uma fralda, um remédio ou uma comemoração de aniversário podem desequilibrar o mês, o que mostra margem de segurança muito estreita.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '14'), ('D11-TR-043', 'O benefício aparece como parte da economia percebida antes mesmo de ser tema específico, o que revela que não é lembrado como política isolada, mas como engrenagem da organização doméstica.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '14'), ('D11-TR-045', 'A comparação com quatro ou cinco anos atrás é ambivalente: há avanços, mas eles não anulam a sensação de vida apertada.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '15'), ('D11-TR-046', 'Reconhecimento de avanços em trabalho, benefício, moradia, cursos, saúde ou estabilidade aparece quase sempre com a ressalva de que custo de vida e insegurança seguem pressionando.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '15'), ('D11-TR-051', 'A vida cotidiana já antecipa a centralidade do benefício, que entra como previsibilidade em uma rotina de baixa margem.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '16'), ('D11-TR-052', 'O benefício aparece como parte da estrutura financeira da casa mesmo antes de ser discutido em profundidade, o que mostra que não é assunto separado da rotina, mas um dos elementos que permite organizar prioridades.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '16'), ('D11-TR-053', 'O dinheiro do benefício tende a ser direcionado ao básico: comida, gás, água, luz, escola, transporte, saúde, roupa, sapato ou despesas dos filhos.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '16'), ('D11-TR-054', 'A função simbólica do benefício vem da função prática: ele protege porque chega onde a vida aperta.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '16'), ('D11-TR-055', 'A importância do benefício varia conforme a situação da mulher, mas sempre opera como redutor de risco: renda central para quem está desempregada, complemento para quem trabalha, respiro para quem enfrenta imprevistos.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '16'), ('D11-TR-056', 'Por aparecer misturado à rotina, qualquer ameaça de atraso, bloqueio ou perda do benefício tende a ser vivida como ameaça à organização da casa inteira, e não apenas à renda individual.', 'mulheres beneficiárias', 'dinheiro no bolso', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '16'), ('D11-TR-061', 'O benefício transforma aperto em alguma margem de controle: não elimina a dificuldade financeira, mas cria margem mínima de previsibilidade para organizar a casa.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'forte', NULL, '18'), ('D11-TR-062', 'O benefício é vivido como dinheiro com função, que já entra no orçamento com destino claro, principalmente comida, gás, contas e despesas dos filhos.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '18'), ('D11-TR-063', 'A força simbólica do benefício vem da regularidade: saber que o dinheiro cai permite planejar antes de a falta virar emergência.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'forte', NULL, '18'), ('D11-TR-066', 'O benefício não é dinheiro solto, mas dinheiro já comprometido com a sustentação da casa, descrito por aquilo que permite pagar: feira, compra, gás, água, luz, escola, transporte, saúde e necessidades dos filhos.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '19'), ('D11-TR-067', 'O benefício organiza o restante da renda: quando cobre parte do básico, o dinheiro do trabalho ou dos bicos pode ir para outras contas.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '19'), ('D11-TR-068', 'O programa não aparece como renda extra, mas como engrenagem do orçamento doméstico.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '19'), ('D11-TR-074', 'A regularidade vale quase tanto quanto o valor: o benefício importa porque permite planejar antes de faltar.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '20'), ('D11-TR-075', 'O valor mensal é importante, mas a previsibilidade do pagamento é o que transforma o benefício em segurança.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '20'), ('D11-TR-076', 'Saber que o dinheiro vai cair permite reservar gás, completar a feira, pagar uma conta ou segurar uma despesa dos filhos.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '20'), ('D11-TR-077', 'A regularidade do pagamento reduz ansiedade e dá sensação de controle em uma rotina de baixa margem.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '20'), ('D11-TR-078', 'Atraso, bloqueio ou suspensão de Benefíciosnão são percebidos apenas como perda de renda, mas como ameaça à organização da casa inteira.', 'mulheres beneficiárias', 'dinheiro no bolso', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '20'), ('D11-TR-079', 'Quanto mais estrutural o benefício na organização da casa, maior o medo diante do cadastro, do bloqueio e do atendimento.', 'mulheres beneficiárias', 'dinheiro no bolso', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '20'), ('D11-TR-080', 'O mesmo benefício muda de significado conforme o momento da família e pode operar como complemento.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '21'), ('D11-TR-081', 'Para quem trabalha, o benefício vira complemento: não substitui salário, mas cria margem para despesas dos filhos ou pequenos alívios.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '21'), ('D11-TR-082', 'Para quem está sem trabalho, o benefício pode ser a base que garante compra, água, luz e alimentação até surgir outra renda.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '21'), ('D11-TR-083', 'O benefício pode operar como respiro, e o mesmo valor pode significar arroz e feijão em um momento e uma pizza com os filhos em outro, o que revela sua elasticidade.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '21'), ('D11-TR-084', 'A variação de significado do benefício impede uma narrativa única da beneficiária, porque o programa acompanha ciclos de vulnerabilidade, recomposição e instabilidade.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '21'), ('D11-TR-086', 'O benefício funciona como porta de entrada para uma rede de proteção: quando conectado a outros apoios, o programa ganha mais valor percebido.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '22'), ('D11-TR-087', 'O benefício aparece articulado a desconto de luz, água, gás, Pé de Meia, dignidade menstrual e outros apoios.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '22'), ('D11-TR-088', 'Quando essas conexões são conhecidas, o programa deixa de parecer um pagamento isolado e passa a ser visto como acesso a uma rede.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '22'), ('D11-TR-089', 'Cada apoio reduz uma pressão específica do orçamento: gás, conta de luz, absorvente, escola, transporte ou permanência dos filhos estudando.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '22'), ('D11-TR-090', 'O risco é a rede existir sem ser plenamente compreendida: parte das mulheres descobre benefícios aos poucos ou não entende por que tem direito a alguns e não a outros.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '22'), ('D11-TR-101', 'O benefício combina três funções: organiza o orçamento, reduz risco e reconhece necessidade legítima.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '24'), ('D11-TR-102', 'O benefício entra no mês com destino claro: comida, gás, luz, água, escola, transporte, saúde e filhos.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '24'), ('D11-TR-103', 'O benefício permite separar o dinheiro da transferência do dinheiro do trabalho, dos bicos ou de outras fontes de renda.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '24'), ('D11-TR-104', 'O benefício transforma uma renda apertada em algum planejamento, mesmo que ainda limitado.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '24'), ('D11-TR-105', 'O benefício cria uma margem mínima de segurança em uma rotina em que qualquer imprevisto pode desorganizar a casa.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '24'), ('D11-TR-106', 'O benefício ajuda a evitar situações extremas, como faltar comida, atrasar conta ou não conseguir resolver uma urgência dos filhos.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '24'), ('D11-TR-107', 'A regularidade do pagamento reduz ansiedade e dá previsibilidade para decidir prioridades antes de a falta virar crise.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '24'), ('D11-TR-111', 'O benefício não muda a vida porque sobra, mas porque organiza: protege a casa, reduz o risco de ruptura e reconhece a dignidade de quem já sustenta a família todos os dias.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '24'), ('D11-TR-112', 'Quanto mais o benefício organiza a casa, mais o bloqueio vira ameaça.', 'mulheres beneficiárias', 'dinheiro no bolso', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '26'), ('D11-TR-113', 'Como o benefício já tem lugar no orçamento, qualquer risco de bloqueio, atraso ou suspensão ameaça a organização da casa inteira.', 'mulheres beneficiárias', 'dinheiro no bolso', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '26'), ('D11-TR-114', 'O cadastro único é porta de acesso e também fonte de ansiedade, porque exige atualizar, comprovar, pesar, acompanhar e entender regras.', 'mulheres beneficiárias', 'dinheiro no bolso', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '26'), ('D11-TR-115', 'O medo não vem apenas da possibilidade de perder o dinheiro, mas da dificuldade de resolver quando algo dá errado.', 'mulheres beneficiárias', 'dinheiro no bolso', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '26'), ('D11-TR-116', 'O medo de perder o benefício existe: Mais por questões burocráticas e menos por mudança de governo', 'mulheres beneficiárias', 'dinheiro no bolso', 'acesso a benefícios e atendimento', 'achado', 'forte', NULL, '26'), ('D11-TR-120', 'O cadastro é reconhecido como caminho para acessar e manter benefícios, mas sua centralidade faz dele uma área de risco permanente.', 'mulheres beneficiárias', 'dinheiro no bolso', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '27'), ('D11-TR-121', 'Atualização, pesagem, vacinação, frequência escolar e comprovação de dados viram tarefas de vigilância para evitar bloqueio.', 'mulheres beneficiárias', 'dinheiro no bolso', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '27'), ('D11-TR-122', 'O bloqueio é mais temido porque afeta dinheiro já comprometido com comida, gás, contas, saúde e filhos.', 'mulheres beneficiárias', 'dinheiro no bolso', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '27'), ('D11-TR-222', 'A ideia de alívio conecta emocionalmente, mas fica genérica sem prova concreta.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação de serviço', 'achado', 'indício', NULL, '40'), ('D11-TR-255', 'A ideia de alívio conecta, mas fica genérica se não provar onde ele aparece.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação de serviço', 'achado', 'indício', NULL, '43'), ('D11-TR-266', 'A peça é útil e informativa, mas precisa transformar o dado em caminho de acesso.', 'mulheres beneficiárias', 'dinheiro no bolso', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '44'), ('D11-TR-318', 'A vida é organizada no limite: comida, gás, luz, saúde, escola e filhos definem a percepção de melhora.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '50'), ('D11-TR-319', 'O benefício é vivido como renda com função: organiza o mês, reduz risco e dá alguma previsibilidade.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '50'), ('D13-TR-137-mb', 'A perda financeira por interrupção do trabalho é sentida com mais força por quem não tem vínculo formal.', 'mulheres beneficiárias', 'dinheiro no bolso', 'mei e trabalho autônomo', 'achado', 'indício', NULL, NULL), ('D13-TR-139-mb', 'Entre quem tem vínculo formal, a crítica recai sobre a defasagem do salário mínimo frente à inflação e ao custo de vida.', 'mulheres beneficiárias', 'dinheiro no bolso', 'salário mínimo', 'achado', 'indício', NULL, NULL), ('D13-TR-141-mb', 'Para quem trabalha por conta própria o problema é a instabilidade; para quem tem vínculo formal, a insuficiência do valor fixo.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, NULL), ('D11-TR-030', 'Mensagens que reconhecem apenas dificuldade financeira podem parecer incompletas.', 'mulheres beneficiárias', 'dinheiro no bolso', 'cuidado e sobrecarga', 'afasta', NULL, NULL, '12'), ('D11-TR-248', 'Afirmar que o remédio estava disponível ou que a conta de luz aliviou pode soar idealizado diante de experiências de falta, aumento de conta ou acesso desigual.', 'mulheres beneficiárias', 'dinheiro no bolso', 'saúde e sus', 'afasta', NULL, NULL, '42'), ('D11-TR-250', 'Quando a experiência concreta contradiz a frase, a rota deixa de comunicar cuidado e passa a provocar contestação.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação de serviço', 'afasta', NULL, NULL, '42'), ('D11-TR-262', 'Há risco de a peça parecer afirmação ampla demais sobre um cotidiano que ainda segue apertado.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'afasta', NULL, NULL, '43'), ('D11-TR-270', 'O dado sobre o número de políticas públicas acessíveis chama atenção, mas fica incompleto se não explicar quais são, para quem valem e como acessar.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'afasta', NULL, NULL, '44'), ('D01-TR-013-mb', 'Mais de 41 milhões de lares brasileiros são chefiados por mulheres; por gerenciarem o orçamento doméstico, são mais sensíveis aos impactos econômicos.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'contexto', NULL, NULL, '13'), ('D01-TR-014', 'Mulheres constituem mais de 84% das titularidades de programas de transferência de renda e sentem mais as variações de qualidade dos serviços públicos.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'contexto', NULL, NULL, '13'), ('D01-TR-017', 'Mais de 97 milhões de pessoas estão inscritas no CadÚnico, 48% da população brasileira, presentes em 5.570 municípios.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'contexto', NULL, NULL, '14'), ('D01-TR-018', 'O Bolsa Família alcança mais de 49 milhões de pessoas; 84% dos lares beneficiários são chefiados por mulheres e 73% por pessoas pretas ou pardas.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'contexto', NULL, NULL, '14'), ('D01-TR-020', '71% dos lares que superaram a insegurança alimentar eram chefiados por mulher, evidência do impacto da transferência de renda.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'contexto', NULL, NULL, '14'), ('D01-TR-030-mb', 'O engajamento nasce de caminho prático, nunca de slogan de superação.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '17'), ('D01-TR-046-mb', 'Mostrar como um Estado presente pode ajudar no alívio do dia a dia por meio de políticas públicas.', 'mulheres beneficiárias', 'dinheiro no bolso', 'atribuição de políticas públicas', 'funciona', NULL, NULL, '21'), ('D01-TR-051', 'Fila, aplicativo instável e regra confusa custam tempo e dignidade; acesso simples também é dinheiro no bolso.', 'mulheres beneficiárias', 'dinheiro no bolso', 'acesso a benefícios e atendimento', 'funciona', NULL, NULL, '22'), ('D10-TR-022', 'O dinheiro não deve ser narrado como fartura, mas como estabilidade mínima: organizar, priorizar, pagar, reservar, cuidar e planejar.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '8'), ('D10-TR-156', 'Dinheiro não é sobra nem consumo: é sustentação da vida.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '32'), ('D10-TR-164', 'A comunicação deve falar menos de economia abstrata e mais de despesas concretas: compra, conta paga, gás reservado, remédio e filho atendido.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '32'), ('D10-TR-165', 'Reposicionar a beneficiária como gestora legítima do orçamento é caminho promissor: ela sabe o que o dinheiro compra, onde falta e como priorizar.', 'mulheres beneficiárias', 'dinheiro no bolso', 'estigma do benefício', 'funciona', NULL, NULL, '32'), ('D10-TR-166', 'Prometer menos "dinheiro que resolve" e mais dinheiro que ajuda a segurar, organizar e abrir margem para planejar.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '32'), ('D10-TR-167', 'A oportunidade é deslocar dinheiro no bolso para a ideia de poder fazer: organizar o mês, reduzir risco, escolher prioridades e recuperar alguma capacidade de planejar.', 'mulheres beneficiárias', 'dinheiro no bolso', 'participação política', 'funciona', NULL, NULL, '33'), ('D10-TR-168', 'A mulher deve aparecer como protagonista desse percurso, transformando renda em cuidado, estabilidade e futuro possível.', 'mulheres beneficiárias', 'dinheiro no bolso', 'cuidado e sobrecarga', 'funciona', NULL, NULL, '33'), ('D10-TR-171', 'Pagador de impostos, beneficiária, aposta, iPhone, fraude, fila, aplicativo e bloqueio são as figuras que materializam a disputa moral sobre o benefício.', 'mulheres beneficiárias', 'dinheiro no bolso', 'endividamento e crédito', 'funciona', NULL, NULL, '34'), ('D10-TR-174', 'Mercado, feira, arroz, feijão, carne, gás, luz, água, cartão, dívida e nome sujo são as figuras que materializam a falta e o aperto.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '34'), ('D10-TR-177', 'Calendário de pagamento, aplicativo do benefício, programa de transferência de renda, compra do mês, conta paga, botijão e remédio são as figuras que materializam controle e organização.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'funciona', NULL, NULL, '34'), ('D10-TR-180', 'Fralda, roupa do filho, lanche, brinquedo, material escolar, dívida quitada e casa abastecida são as figuras que materializam respiro e possibilidade.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '34'), ('D10-TR-181', 'O dinheiro aparece primeiro como falta, na dimensão disfórica, mas pode ser narrado como retomada de controle, na dimensão eufórica.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, '34'), ('D10-TR-182', 'As narrativas de dinheiro no bolso devem mostrar a passagem do aperto para algum controle sobre o mês.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, '35'), ('D10-TR-183', 'A transformação a ser narrada não é drástica, mas de estabilidade mínima.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '35'), ('D10-TR-188', 'A política pública funciona como adjuvante narrativo: não substitui a ação da mulher, mas oferece recursos e condições para que ela transforme renda limitada em cuidado, estabilidade e futuro possível.', 'mulheres beneficiárias', 'dinheiro no bolso', 'atribuição de políticas públicas', 'funciona', NULL, NULL, '35'), ('D10-TR-189', 'O ponto comum dos territórios é deslocar a narrativa de "dinheiro que resolve" para dinheiro que devolve algum poder de organização.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '36');
